// Render the machine reference — `docs/reference/machines.md` — from the registry (UPS-DOC-05:
// reference that can be derived from source is generated, never hand-copied). Pure (no I/O, no
// clock), so the freshness test (`reference.test.ts`) and the CLI wrapper
// (`app/scripts/gen-reference.ts`) render the same bytes. The prose on HOW each machine compiles
// stays hand-written in docs/ARCHITECTURE.md § 4; this file only lists what the registry holds.

import type { FieldDef, MachineCategory, MachineDef } from './registry';

/** Repo-relative path of the generated file. */
export const MACHINE_REFERENCE_PATH = 'docs/reference/machines.md';
/** The command that rebuilds it — named in the file's GENERATED header. */
export const MACHINE_REFERENCE_COMMAND = 'cd app && npm run reference';

const CATEGORIES: { category: MachineCategory; title: string; role: string }[] = [
  {
    category: 'trigger',
    title: 'Triggers',
    role: 'start an assembly line — they map to the workflow `on:` block',
  },
  {
    category: 'processor',
    title: 'Processors',
    role: 'agents, filters, gates and loop machines between a trigger and its sinks',
  },
  {
    category: 'sink',
    title: 'Sinks',
    role: 'what a line does to the repository — or, downstream of an agent, its obligations',
  },
];

/** A Markdown code span that survives backticks in the value and pipes inside a table cell. */
function code(value: string): string {
  const fence = value.includes('`') ? '``' : '`';
  const pad = value.startsWith('`') || value.endsWith('`') ? ' ' : '';
  return `${fence}${pad}${value}${pad}${fence}`.replace(/\|/g, '\\|');
}

/** Prose for a table cell or a one-line paragraph: one line, pipes and `<` escaped. */
function cell(text: string): string {
  return text
    .replace(/\s*\n\s*/g, ' ')
    .replace(/\|/g, '\\|')
    .replace(/</g, '&lt;')
    .trim();
}

function formatDefault(value: unknown): string {
  if (value === undefined) return '—';
  if (value === '') return '(empty)';
  if (typeof value === 'string') return code(value);
  return code(JSON.stringify(value));
}

function formatKind(field: FieldDef): string {
  if (field.kind === 'select' && field.options?.length) {
    return `select: ${field.options.map(code).join(' · ')}`;
  }
  return field.kind;
}

function formatNotes(field: FieldDef, defaultValue: unknown): string {
  const parts: string[] = [];
  if (field.help) parts.push(cell(field.help));
  // A placeholder that only repeats the default adds nothing; one that differs is an example.
  if (field.placeholder && field.placeholder !== String(defaultValue ?? '')) {
    const examples = field.placeholder
      .split('\n')
      .map((line) => line.trim())
      .filter(Boolean);
    parts.push(`e.g. ${examples.map(code).join('; ')}`);
  }
  return parts.join(' ') || '—';
}

function anchorFor(type: string): string {
  return type.toLowerCase().replace(/[^a-z0-9 _-]/g, '');
}

function renderMachine(m: MachineDef): string[] {
  const out = [`### \`${m.type}\``, '', `${m.icon} **${m.label}** — ${cell(m.blurb)}`, ''];
  out.push(`Canvas summary with the defaults: ${code(m.describe({ ...m.defaults }))}`, '');
  if (m.fields.length === 0) {
    out.push('No config fields.', '');
  } else {
    out.push('| Field | Label | Kind | Default | Notes |', '| --- | --- | --- | --- | --- |');
    for (const f of m.fields) {
      out.push(
        `| ${code(f.key)} | ${cell(f.label)} | ${formatKind(f)} | ${formatDefault(m.defaults[f.key])} | ${formatNotes(f, m.defaults[f.key])} |`,
      );
    }
    out.push('');
  }
  const fieldKeys = new Set(m.fields.map((f) => f.key));
  const hidden = Object.keys(m.defaults).filter((k) => !fieldKeys.has(k));
  if (hidden.length > 0) {
    out.push(
      `Defaults with no editor field: ${hidden.map((k) => `${code(k)} = ${formatDefault(m.defaults[k])}`).join(', ')}.`,
      '',
    );
  }
  return out;
}

/** The whole reference document, ending in exactly one newline. */
export function renderMachineReference(machines: readonly MachineDef[]): string {
  const count = (c: MachineCategory) => machines.filter((m) => m.category === c).length;
  const out: string[] = [
    `<!-- GENERATED by \`${MACHINE_REFERENCE_COMMAND}\` from app/src/machines/registry.ts — do not edit by hand -->`,
    '# Machine reference',
    '',
    '> Every machine type the canvas offers — its id, category, blurb, config fields and defaults — generated from the machine registry.',
    '',
    `${machines.length} machine types: ${count('trigger')} triggers · ${count('processor')} processors · ${count('sink')} sinks. How each one compiles (guards, grants, obligations, emitted jobs) is explained in [ARCHITECTURE.md § 4](../ARCHITECTURE.md#4-machine-catalog-v0); the user-facing tour is the app's Docs tab (\`_docs/machines-and-belts.md\`). Add a machine with \`/add-machine\`, then regenerate this file.`,
    '',
    '| Type | Category | Machine | Config fields |',
    '| --- | --- | --- | --- |',
  ];
  for (const { category } of CATEGORIES) {
    for (const m of machines.filter((x) => x.category === category)) {
      const fields = m.fields.map((f) => code(f.key)).join(', ') || '—';
      out.push(
        `| [${code(m.type)}](#${anchorFor(m.type)}) | ${category} | ${m.icon} ${cell(m.label)} | ${fields} |`,
      );
    }
  }
  out.push('');
  for (const { category, title, role } of CATEGORIES) {
    const group = machines.filter((m) => m.category === category);
    if (group.length === 0) continue;
    out.push(`## ${title}`, '', `${title} ${role}.`, '');
    for (const m of group) out.push(...renderMachine(m));
  }
  while (out[out.length - 1] === '') out.pop();
  return `${out.join('\n')}\n`;
}
